import * as THREE from 'three';

const canvas = document.querySelector('#world');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x9eb8b2);
scene.fog = new THREE.FogExp2(0x9eb8b2, 0.00155);
const camera = new THREE.PerspectiveCamera(58, innerWidth / innerHeight, 0.1, 1500);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;

scene.add(new THREE.HemisphereLight(0xdce9e0, 0x455b43, 2.05));
const sun = new THREE.DirectionalLight(0xffdfab, 3.2);
sun.position.set(-90, 150, 100); sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -145; sun.shadow.camera.right = 145; sun.shadow.camera.top = 145; sun.shadow.camera.bottom = -145;
sun.shadow.bias = -0.00025; scene.add(sun);
const fill = new THREE.DirectionalLight(0x91c8db, 1.25); fill.position.set(120, 55, -130); scene.add(fill);

const clamp = THREE.MathUtils.clamp;
const mix = THREE.MathUtils.lerp;
const V = (x=0,y=0,z=0)=>new THREE.Vector3(x,y,z);
const mat = (color, roughness=.8, extra={})=>new THREE.MeshStandardMaterial({color,roughness,...extra});
const mats = {
  terrain: new THREE.MeshStandardMaterial({vertexColors:true,roughness:.96}),
  water: new THREE.MeshPhysicalMaterial({color:0x55a9ae,roughness:.23,metalness:.15,transparent:true,opacity:.83,clearcoat:.8,clearcoatRoughness:.2}),
  dark:mat(0x26373a,.92), scale:mat(0x406d64,.62), belly:mat(0xb9a47d,.8), wing:mat(0x75463d,.78,{side:THREE.DoubleSide}), wingLit:mat(0xa5654a,.76,{side:THREE.DoubleSide}), horn:mat(0xe4c992,.65), gold:mat(0xe7be68,.3,{emissive:0x58320b,emissiveIntensity:.42}), bark:mat(0x604637), leaf:mat(0x3e694a), leaf2:mat(0x658655), roof:mat(0x57433b), stone:mat(0x817c69), crystal:mat(0x75edc9,.22,{emissive:0x24af8c,emissiveIntensity:1.7}), ember:mat(0xffb74f,.25,{emissive:0xf06417,emissiveIntensity:2.1}),
};

// A broad, procedural valley: a warm grass basin ringed by high, wooded ridges.
function heightAt(x,z){
  const ridges = 9*Math.sin(x*.027+Math.sin(z*.019)*1.5)+7*Math.cos(z*.035+x*.012)+4*Math.sin((x+z)*.055);
  const peaks = 43*Math.exp(-((x+105)**2+(z+35)**2)/4400)+34*Math.exp(-((x-100)**2+(z-100)**2)/5200)+28*Math.exp(-((x+5)**2+(z-145)**2)/3900);
  const rim = Math.max(0, Math.hypot(x,z)-130)*.31;
  const basin = -4*Math.exp(-(x*x+z*z)/2500);
  return Math.max(-3, 5+ridges+peaks+rim+basin);
}
function makeTerrain(){
  const n=145, size=560, geo=new THREE.PlaneGeometry(size,size,n,n); geo.rotateX(-Math.PI/2);
  const pos=geo.attributes.position, colors=[];
  const low=new THREE.Color(0x667c4d), mid=new THREE.Color(0x8c9560), high=new THREE.Color(0x9d9876), peak=new THREE.Color(0xc0b89f);
  for(let i=0;i<pos.count;i++){
    const x=pos.getX(i), z=pos.getZ(i), h=heightAt(x,z); pos.setY(i,h);
    let c=h<14?low.clone().lerp(mid,clamp((h+5)/23,0,1)):mid.clone().lerp(high,clamp((h-14)/27,0,1));
    if(h>40)c.lerp(peak,clamp((h-40)/40,0,.7));
    const noise=(Math.sin(x*.27+z*.13)*Math.sin(z*.2-x*.09))*.045;c.offsetHSL(0,0,noise);
    colors.push(c.r,c.g,c.b);
  }
  geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.computeVertexNormals();
  const ground=new THREE.Mesh(geo,mats.terrain);ground.receiveShadow=true;scene.add(ground);
}
makeTerrain();

// Winding river and two clear alpine tarns, nestled directly into the terrain.
function makeWater(){
  const points=[];
  for(let i=0;i<=55;i++){const z=-235+i*8.6;const x=45+Math.sin(i*.15)*28+Math.sin(i*.047)*44;points.push(V(x,2.1,z));}
  const curve=new THREE.CatmullRomCurve3(points);const verts=[],idx=[];const segments=300;
  for(let i=0;i<=segments;i++){const t=i/segments,p=curve.getPoint(t),tan=curve.getTangent(t),side=new THREE.Vector3(-tan.z,0,tan.x).normalize();const w=5+2*Math.sin(t*35)**2;verts.push(p.x+side.x*w,p.y,p.z+side.z*w,p.x-side.x*w,p.y,p.z-side.z*w);if(i<segments){const a=i*2;idx.push(a,a+1,a+2,a+1,a+3,a+2);}}
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setIndex(idx);g.computeVertexNormals();const river=new THREE.Mesh(g,mats.water);scene.add(river);
  const makeLake=(x,z,rx,rz)=>{const m=new THREE.Mesh(new THREE.CircleGeometry(1,72),mats.water);m.rotation.x=-Math.PI/2;m.position.set(x,2.3,z);m.scale.set(rx,rz,1);scene.add(m);};
  makeLake(-66,-20,26,17);makeLake(116,34,32,21);makeLake(-95,135,18,12);
}
makeWater();

// Handmade village props: cabins, windmill, stone watchtowers and a scatter of pines.
const rand=(seed)=>{let x=Math.sin(seed*127.1+311.7)*43758.5453;return x-Math.floor(x);};
function addCabin(x,z,s=1){
 const g=new THREE.Group();g.position.set(x,heightAt(x,z),z);g.scale.setScalar(s);scene.add(g);
 const body=new THREE.Mesh(new THREE.BoxGeometry(6,4.2,5),mat(0x927453));body.position.y=2.2;body.castShadow=true;body.receiveShadow=true;g.add(body);
 const roof=new THREE.Mesh(new THREE.ConeGeometry(4.5,3.3,4),mats.roof);roof.rotation.y=Math.PI/4;roof.position.y=5.8;roof.castShadow=true;g.add(roof);
 const door=new THREE.Mesh(new THREE.BoxGeometry(1.25,2.5,.16),mat(0x3d3128));door.position.set(0,1.35,2.57);g.add(door);
 const glow=new THREE.PointLight(0xffb96c,2,12);glow.position.set(1,2.2,2.8);g.add(glow);
 return g;
}
function addTree(x,z,seed,scale=1){
 const y=heightAt(x,z);if(y>48)return;
 const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.24*scale,.48*scale,3.7*scale,7),mats.bark);trunk.position.set(x,y+1.6*scale,z);trunk.castShadow=true;scene.add(trunk);
 for(let j=0;j<3;j++){const c=new THREE.Mesh(new THREE.ConeGeometry((2.2-j*.32)*scale,(3.4-j*.2)*scale,7),j===1?mats.leaf2:mats.leaf);c.position.set(x,y+(3.5+j*1.35)*scale,z);c.castShadow=true;scene.add(c);}
}
for(let i=0;i<260;i++){let x=(rand(i+11)-.5)*470,z=(rand(i+801)-.5)*470;if(Math.hypot(x,z)<43)continue;if(Math.hypot(x-25,z+55)<42)continue;addTree(x,z,i+3,.65+rand(i+22)*.9);}
addCabin(18,-58,1.15);addCabin(31,-63,.72);addCabin(12,-68,.74);addCabin(-112,-14,.85);addCabin(138,15,.8);addCabin(-113,143,.8);
// Tiny watchtowers on distant high ground.
for(const [x,z] of [[-126,-60],[150,105],[-25,174]]){const y=heightAt(x,z);const tower=new THREE.Group();tower.position.set(x,y,z);scene.add(tower);const base=new THREE.Mesh(new THREE.CylinderGeometry(3,4,12,8),mats.stone);base.position.y=6;base.castShadow=true;tower.add(base);const cap=new THREE.Mesh(new THREE.ConeGeometry(4.5,4,8),mats.roof);cap.position.y=14;tower.add(cap);}

// Sunlit cloud wisps made of layered soft ellipsoids.
const cloudMat=new THREE.MeshBasicMaterial({color:0xf2eee0,transparent:true,opacity:.37,depthWrite:false});
for(let i=0;i<14;i++){const cloud=new THREE.Group();cloud.position.set((rand(i+412)-.5)*430,68+rand(i+30)*38,(rand(i+204)-.5)*430);cloud.userData.drift=.4+rand(i+60)*.7;for(let j=0;j<5;j++){const puff=new THREE.Mesh(new THREE.SphereGeometry(1,12,10),cloudMat);puff.scale.set(8+rand(i*7+j)*8,2+rand(i+j*3)*3,5+rand(i*2+j)*6);puff.position.set((j-2)*7,rand(i+j)*2,rand(i+j*2)*4);cloud.add(puff);}scene.add(cloud);clouds.push(cloud);}
const clouds=[];

// Warm sky disc.
const sunBall=new THREE.Mesh(new THREE.SphereGeometry(8,20,16),new THREE.MeshBasicMaterial({color:0xffe6b5}));sunBall.position.set(-250,185,-310);scene.add(sunBall);

