// A custom-built sky drake, with plated scales, hooked horns, ribbed wings and a tapering tail.
function cylinderBetween(parent,a,b,r1,r2,material,segments=8){const av=V(...a),bv=V(...b),dir=bv.clone().sub(av);const m=new THREE.Mesh(new THREE.CylinderGeometry(r2,r1,dir.length(),segments),material);m.position.copy(av.add(bv).multiplyScalar(.5));m.quaternion.setFromUnitVectors(V(0,1,0),dir.normalize());m.castShadow=true;parent.add(m);return m;}
function sphere(parent,material,pos,scale,detail=12){const m=new THREE.Mesh(new THREE.SphereGeometry(1,detail,Math.max(8,detail-3)),material);m.position.set(...pos);m.scale.set(...scale);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function createDragon(){
 const root=new THREE.Group();scene.add(root);const body=new THREE.Group();root.add(body);body.rotation.order='YXZ';
 sphere(body,mats.scale,[0,0,0],[1.35,.8,2.25],20);sphere(body,mats.belly,[0,-.38,-.1],[1.12,.43,1.8],16);
 // neck, crown, muzzle and expressive amber eyes
 cylinderBetween(body,[0,.25,-1.45],[0,.65,-2.85],.48,.31,mats.scale,12);
 sphere(body,mats.scale,[0,.66,-2.92],[.48,.46,.64],16);sphere(body,mats.dark,[0,.53,-3.39],[.37,.25,.5],12);
 for(const s of [-1,1]){sphere(body,mats.gold,[s*.34,.84,-3.02],[.105,.12,.1],10);sphere(body,mat(0x171e1c,.3),[s*.36,.84,-3.105],[.038,.075,.035],8);cylinderBetween(body,[s*.25,1.02,-2.72],[s*.38,1.72,-2.9],.19,.015,mats.horn,8);cylinderBetween(body,[s*.32,.56,-3.36],[s*.47,.65,-3.55],.09,.025,mats.horn,6);}
 // dorsal spines
 for(let i=0;i<9;i++){let z=-1.85+i*.48;const size=.19*(1-Math.abs(i-4)/8);cylinderBetween(body,[0,.68,z],[0,.68+size,z+.08],size*.52,.012,mats.horn,5);}
 // four hooked legs
 for(const s of [-1,1])for(const z of [-1.12,1.15]){const hip=[s*.83,-.2,z],knee=[s*1.1,-.82,z+.12],foot=[s*1.1,-1.02,z-.12];cylinderBetween(body,hip,knee,.28,.18,mats.scale);cylinderBetween(body,knee,foot,.18,.13,mats.scale);for(let t=0;t<3;t++)cylinderBetween(body,[foot[0]+s*(t-1)*.1,foot[1]-.02,foot[2]-.1],[foot[0]+s*(t-1)*.16,foot[1]-.04,foot[2]-.34],.075,.008,mats.horn,5);}
 // long articulated tail
 let prev=[0,0,1.65];for(let i=1;i<=8;i++){const t=i/8,next=[Math.sin(t*1.8)*.16,-.05+Math.sin(t*2)*.08,1.65+t*2.35];cylinderBetween(body,prev,next,.37*(1-(i-1)/9),.37*(1-i/9),i%2?mats.scale:mats.dark,8);prev=next;}
 const fin=new THREE.Mesh(new THREE.ConeGeometry(.42,.9,5),mats.wingLit);fin.position.set(0,.01,4.27);fin.rotation.x=Math.PI/2;fin.scale.set(1,.7,.25);body.add(fin);
 const wings=[];
 for(const s of [-1,1]){const pivot=new THREE.Group();pivot.position.set(s*1.05,.46,-.25);body.add(pivot);if(s<0)pivot.scale.x=-1;
  const shape=new THREE.Shape();shape.moveTo(0,0);shape.lineTo(1.05,.43);shape.lineTo(2.35,1.75);shape.lineTo(2.22,.28);shape.lineTo(4.65,-.55);shape.lineTo(2.4,-.17);shape.lineTo(2.05,-1.12);shape.lineTo(1.45,-.35);shape.lineTo(.1,-.62);shape.closePath();
  const wing=new THREE.Mesh(new THREE.ShapeGeometry(shape,2),mats.wing);wing.castShadow=true;pivot.add(wing);
  cylinderBetween(pivot,[0,0,.03],[2.35,1.75,.03],.09,.04,mats.scale,7);cylinderBetween(pivot,[0,0,.04],[4.65,-.55,.04],.1,.035,mats.scale,7);cylinderBetween(pivot,[.05,-.05,.05],[2.22,.28,.05],.07,.035,mats.scale,7);cylinderBetween(pivot,[.08,-.05,.05],[2.05,-1.12,.05],.07,.03,mats.scale,7);cylinderBetween(pivot,[2.35,1.75,.05],[2.22,.28,.05],.045,.025,mats.wingLit,6);cylinderBetween(pivot,[2.22,.28,.05],[2.05,-1.12,.05],.045,.02,mats.wingLit,6);cylinderBetween(pivot,[2.22,.28,.05],[4.65,-.55,.05],.05,.02,mats.wingLit,6);
  wings.push({pivot,sign:s});}
 return {root,body,wings};
}
const dragon=createDragon();dragon.root.position.set(0,17,12);

// Three beacon sites call to the rider from different corners of the open valley.
const shrines=[];
function makeShrine(x,z,index){
 const y=heightAt(x,z)+.5,g=new THREE.Group();g.position.set(x,y,z);scene.add(g);
 const dais=new THREE.Mesh(new THREE.CylinderGeometry(3.2,3.8,1.2,8),mats.stone);dais.position.y=.6;dais.castShadow=true;dais.receiveShadow=true;g.add(dais);
 for(let j=0;j<4;j++){const pillar=new THREE.Mesh(new THREE.BoxGeometry(.4,2.4,.4),mats.stone);const a=j*Math.PI/2+Math.PI/4;pillar.position.set(Math.cos(a)*2.2,1.65,Math.sin(a)*2.2);pillar.castShadow=true;g.add(pillar);}
 const crystal=new THREE.Mesh(new THREE.OctahedronGeometry(1.05,0),mats.crystal);crystal.position.y=2.8;crystal.rotation.z=.2;g.add(crystal);
 const light=new THREE.PointLight(0x57f0cf,3.5,30);light.position.y=3;g.add(light);
 const ring=new THREE.Mesh(new THREE.TorusGeometry(2.3,.035,6,56),mats.gold);ring.rotation.x=Math.PI/2;ring.position.y=1.5;g.add(ring);
 const flame=new THREE.PointLight(0xffbe66,1.8,12);flame.position.y=4.4;g.add(flame);
 const labels=['Mosslight Hollow','Whispering Tarn','Cinderwatch Rise'];shrines.push({x,z,y,group:g,crystal,light,ring,flame,name:labels[index],collected:false});
}
makeShrine(-67,-20,0);makeShrine(116,34,1);makeShrine(-104,132,2);

// Curious ember wisps roam the air. Fire breath can scatter them for a little healing.
const wisps=[];
function makeWisp(x,z,seed){const g=new THREE.Group();g.position.set(x,heightAt(x,z)+12,z);scene.add(g);const core=new THREE.Mesh(new THREE.IcosahedronGeometry(.72,1),new THREE.MeshBasicMaterial({color:0xff9b58}));g.add(core);const glow=new THREE.PointLight(0xff6b43,2.3,18);g.add(glow);for(let i=0;i<3;i++){const orb=new THREE.Mesh(new THREE.SphereGeometry(.12,8,6),mats.ember);g.add(orb);orb.position.set(Math.cos(i*2.1)*1.1,Math.sin(i*2.1)*.8,Math.sin(i*2.1)*.9);}wisps.push({group:g,core,glow,seed,health:2,alive:true,home:V(x,heightAt(x,z)+12,z)});}
makeWisp(-28,-89,1);makeWisp(90,-74,2);makeWisp(145,90,3);makeWisp(-144,64,4);makeWisp(7,128,5);

